package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.ParseError;
import org.jsoup.parser.Parser;
import org.jsoup.parser.TagToken;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_siblingIndex_TriageGen2Test {

    private Node parentNode;
    private Node child1;
    private Node child2;
    private Node child3;

    @Before
    public void setUp() {
        parentNode = new Node(Tag.valueOf("div"));
        child1 = new Node(Tag.valueOf("span"));
        child2 = new Node(Tag.valueOf("p"));
        child3 = new Node(Tag.valueOf("a"));

        parentNode.addChildren(child1, child2, child3);
    }

    @Test
    public void testSiblingIndex_WithFirstChild() {
        assertEquals(0, child1.siblingIndex());
    }

    @Test
    public void testSiblingIndex_WithMiddleChild() {
        assertEquals(1, child2.siblingIndex());
    }

    @Test
    public void testSiblingIndex_WithLastChild() {
        assertEquals(2, child3.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NoChildren() {
        Node emptyNode = new Node(Tag.valueOf("div"));
        assertEquals(-1, emptyNode.siblingIndex());
    }

    @Test
    public void testSiblingIndex_WithUnaddedChild() {
        Node unlinkedChild = new Node(Tag.valueOf("b"));
        assertEquals(-1, unlinkedChild.siblingIndex());
    }

    @Test(expected = NullPointerException.class)
    public void testSiblingIndex_WithNullSiblingIndex() {
        Node nullSiblingIndexNode = new Node();
        nullSiblingIndexNode.setSiblingIndex(null);
        nullSiblingIndexNode.siblingIndex();
    }
}
